result:
.seckill-box{
	background: #fff

	.hd{
		display: flex
		justify-content: space-between
		align-items: center
		background-repeat: no-repeat;
		background-size: 100% 100%;
		width: 100%;
		height: 48px;
		padding: 0 12px;
		.right{
			color: #fff;
			font-size: 12px;
			.iconfont{
				font-size: 12px;
			}
		}
		.left{
			display: flex
			align-items: center
			.text{
				font-size: 16px;
				margin-right: 8px
			}
			.line{
				width: 1px;
				height: 14px;
				background: #DDDDDD;
				margin: 0 10px;
			}
			img{
				width: 70px
				height: 16px
			}
			.pictrue{
				width: 43px;
				height: 18px;
				img{
					width: 100%;
					height: 100%;
				}
			}
			.tips {
				font-size: 13px
				color: #fff
				font-weight:400;
				margin-left: 6px;
			}
		}
	}
	.list-wrapper{
		display: flex;
		justify-content: center;
		overflow: hidden;
		padding: 10px;
		width: 100%;
		&.on{
			display: block;
		}
		&.on2{
			flex-wrap: wrap;
			justify-content: flex-start;
		}
		&.on3{
			justify-content: flex-start;
			padding-right: 0;
		}
		.itemTwo,.itemThree{
			width: 48%;
			position: relative;
			margin-right: 11px;
			margin-top: 15px;

			.item{
				height: 50px;
			}

			.item2{
				height: 20px;
			}

			&:nth-child(1){
				margin-top: 0;
			}

			&:nth-child(2){
				margin-top: 0;
			}

			&:nth-of-type(2n){
				margin-right: 0;
			}

			.empty-box{
				width: 100%;
				height: 162px;
				background-color: #F3F9FF;
				img{
					width: 64px;
					height: 50px;
					display: block
				}
			}
			.title{
				font-size: 14px;
				color: #333333;
				margin-top: 8px;
				.name{
					flex: 1
				}
				.label{
					width: 40px;
					height: 15px;
					border-radius: 3px;
					margin-right: 5px;
					.labelBg{
						width: 100%;
						height: 100%;
						text-align: center;
						line-height: 15px;
						background-color: rgba(255,255,255,0.9);
						font-size: 11px;
						border-radius: 2px;
					}
				}
			}
			.price{
				font-weight: 600;
				font-size: 12px;
				&.on{
					margin-top: 8px;
				}
				.num{
					font-size: 16px;
				}
			}
			.yprice{
				font-size: 11px;
				text-decoration: line-through;
				&.on{
					margin-top: 9px;
				}
			}
			.bnt{
				width: 57px;
				height: 26px;
				border-radius: 13px;
				text-align: center;
				line-height: 26px;
				position: absolute;
				right: 0;
				bottom:0;
				font-size: 12px;
				color: #FFFFFF;
				&.on{
					bottom:-4px;
				}
			}
		}

		.itemThree{
			width: 112px;
			margin-top: 0;
			margin-right: 10px !important;
			.item{
				height: 45px;
			}
			.item2{
				height: 29px;
			}
			.empty-box{
				height: 112px;
				position: relative;
				.label{
					width: 42px;
					height: 15px;
					border-radius: 8px;
					font-size: 11px;
					text-align: center;
					line-height: 15px;
					left:5px;
					top:5px;
					position: absolute;
					.labelBg{
						background-color: rgba(255,255,255,0.9);
					}
				}
			}
			.title{
				font-size: 13px;
				margin-top: 6px;
			}
			.price{
				font-size: 11px;
				height: 20px;
				&.on{
					margin-top: 1px;
				}
			}
			.yprice{
				&.on{
					margin-top: 1px;
				}
			}
		}

		.itemOne{
			position: relative;

			&~.itemOne{
				margin-top: 15px;
			}
			.empty-box{
				width: 120px;
				height: 120px;
				margin-right: 12px;
				background-color: #F3F9FF;
				img{
					width: 64px;
					height: 50px;
					display: block
				}
			}
			.text{
				flex: 1;
				.top{
					height: 78px;
					.label{
						width: 96px;
						font-size: 11px;
						border-radius: 3px;
						.labelBg{
							display: flex;
							background-color: rgba(255,255,255,0.9);
							border-radius: 3px;
							.num{
								border-radius: 3px 0 0 3px;
								color: #fff;
								width: 37px;
								text-align: center;
								margin-right: 4px;
							}
						}
					}
				}
				.bottom{
					height: 42px;
				}
				.name{
					font-size: 14px;
					color: #333333;
					margin-bottom: 6px;
				}
				.price{
					font-size: 12px;
					color: #E93323;
					.label{
						font-weight: 600;
						margin-left: 4px;
					}
					.num{
						font-size: 16px;
						font-weight: 600;
					}
				}
				.yprice{
					color: #999999;
					font-size: 12px;
					.num{
						margin-left: 4px;
					}
				}
				.bnt{
					width: 60px;
					height: 28px;
					background: linear-gradient(90deg, #FF7931 0%, #E93323 100%);
					border-radius: 25px;
					text-align: center;
					line-height: 28px;
					color: #FFFFFF;
					font-size: 12px;
					position: absolute;
					right: 0;
					bottom: 0;
				}
			}
		}

		.list-item{
			width: 31.47%;
			margin-top: 10px;

			&~.list-item{
				margin-left: 9px;
			}

			&:nth-of-type(3n-2){
				margin-left: 0;
			}

			&:nth-child(1),&:nth-child(2),&:nth-child(3){
				margin-top: 0;
			}

			.img-box{
				border-radius: 6px;
				position: relative;
				width: 100%
				height: 106px;

				.empty-box{
					background-color: #F3F9FF;
					position: relative;
					img{
						width: 65px;
						height: 50px;
						display: block;
					}
					.label{
						width: 42px;
						height: 15px;
						border-radius: 8px;
						font-size: 11px;
						text-align: center;
						line-height: 15px;
						left:5px;
						top:5px;
						position: absolute;
						.labelBg{
							background-color: rgba(255,255,255,0.9);
						}
					}
				}
			}
			.title{
				margin-top: 8px
				font-size: 13px
				color: #333
			}
			.price{
				line-height: 22px;
				position: relative;
				border-radius: 0 4px 4px 0;
				font-size: 16px;
				margin-top: 1px;
				font-weight: 600;
				height: 20px;

				span{
					font-size: 11px;
					margin-right: 2px;
				}

				img{
					width: 12px;
					height: 22px;
					display: block;
					position: absolute;
					left:-4px;
					top:0
				}
			}
			.yprice{
				color: #999;
				font-size: 12px;
				text-decoration: line-through;
			}
		}
	}
}
